<template>
  <div class="leva-playground">
    <component
      :is="playground"
      v-if="playground"
      :components="componentsMap"
      :schemas="schemasMap"
      :presets="presetsMap"
      :listeners="listenersMap"
      :stage-classes="stageClassMap"
      :stage-styles="stageStyleMap"
      :slot-html="slotHtmlMap"
    />
  </div>
</template>

<script setup lang="ts">
import { computed, defineAsyncComponent, h } from 'vue'
import type { Component } from 'vue'
import { loadPanelLib } from '../configs/remote'

/**
 * 单个示例的属性实验台：把「一个组件 + 它的 propsSchema」包成 PropsPlayground。
 *
 * 每个 tab 只需要传组件和 schema，面板、重新挂载、复杂 props 的固定值
 * 都在这里统一处理，页面里不再出现第二份面板加载逻辑。
 */
const props = defineProps<{
  /** 组件名，同时作为 components / schemas 映射的 key */
  name: string
  /** 要预览的组件（远端或本地组件都行） */
  component?: Component | null
  /** 组件的 propsSchema.json 内容 */
  schema?: unknown[]
  /** 面板不生成控件的复杂 props，如 items / storageKey */
  presets?: Record<string, unknown>
  /** 组件事件监听，如 { select: (item) => ... } */
  listeners?: Record<string, (...args: any[]) => void>
  /** 预览舞台的附加 class */
  stageClass?: string
  /** 预览舞台的内联样式，如 { height: '480px', background: '#f6f7a7' } */
  stageStyle?: Record<string, string>
  /** 插槽的 HTML 内容，如 { default: '<p>内容</p>', title: '标题' } */
  slotHtml?: Record<string, string>
}>()

const PanelError = {
  render: () =>
    h(
      'p',
      { class: 'leva-playground__hint' },
      '属性面板加载失败：确认 libs-vue3-leva 已启动（http://localhost:10040）',
    ),
}

const playground = defineAsyncComponent({
  loader: async () => {
    const lib = await loadPanelLib()
    if (!lib || !lib.PropsPlayground) {
      throw new Error('libs-vue3-leva 未导出 PropsPlayground')
    }
    return lib.PropsPlayground
  },
  errorComponent: PanelError,
  timeout: 10000,
})

const componentsMap = computed(() => (props.component ? { [props.name]: props.component } : {}))
const schemasMap = computed(() => ({ [props.name]: props.schema || [] }))
const presetsMap = computed(() => ({ [props.name]: props.presets || {} }))
const listenersMap = computed(() => ({ [props.name]: props.listeners || {} }))
const stageClassMap = computed(() => (props.stageClass ? { [props.name]: props.stageClass } : {}))
const stageStyleMap = computed(() => (props.stageStyle ? { [props.name]: props.stageStyle } : {}))
const slotHtmlMap = computed(() => ({ [props.name]: props.slotHtml || {} }))
</script>

<style scoped>
.leva-playground {
  min-width: 0;
}

.leva-playground__hint {
  margin: 0;
  padding: 24px;
  color: var(--demo-muted);
  font-size: 13px;
}
</style>
